if(game.world===0)say('Xeon desperta. Há uma voz além do silêncio.');else say(`Você retornou a ${worlds[game.world].name}.`);requestAnimationFrame(loop)}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function circle(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function drawTile(x,y,kind){const w=worlds[game.world],v=(x*11+y*7+game.world*3)%5;rect(x*T,y*T,T,T,v<2?w.alt:w.floor);if(!map[y][x]){if((x*31+y*17)%19===0){rect(x*T+5,y*T+8,2,2,w.accent+'55');rect(x*T+22,y*T+24,3,2,w.sky)}}else{rect(x*T,y*T,T,T,w.wall);rect(x*T+2,y*T+2,T-4,T-7,w.alt);rect(x*T+3,y*T+3,T-6,3,w.accent+'55');rect(x*T+4,y*T+T-5,T-8,3,'#0005');if(game.world===1){rect(x*T+6,y*T+7,20,20,'#253c30');rect(x*T+9,y*T+9,14,15,'#527055')}if(game.world===2){rect(x*T+7,y*T+8,18,3,w.accent);rect(x*T+9,y*T+14,14,2,'#7590b2')}if(game.world===3){rect(x*T+7,y*T+7,18,18,'#3a3027');rect(x*T+11,y*T+10,10,10,'#947045')}if(game.world===4){rect(x*T+4,y*T+6,24,24,'#354136');rect(x*T+8,y*T+5,16,6,'#697457')}if(game.world===5){rect(x*T+6,y*T+8,20,18,'#315269');rect(x*T+9,y*T+11,14,12,'#547983')}}}
function drawDecoration(){const w=worlds[game.world];for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)drawTile(x,y); // landmark silhouettes
if(game.world===1){for(const x of [3,26]){rect(x*T,4*T,2*T,3*T,'#27332d');rect((x+1)*T-3,3*T,8,4*T,'#384a3e');for(let j=0;j<4;j++)rect((x+1)*T-8+j*4,4*T+j*10,3,4,'#e6b987')}}
if(game.world===2){for(const x of [3,24]){rect(x*T,3*T,3*T,5*T,'#1c2438');for(let j=0;j<4;j++){rect(x*T+8,3*T+10+j*22,48,3,'#4e607d');rect(x*T+15+j%2*13,3*T+15+j*22,4,8,['#56d8e6','#e8789a','#9884ec'][j%3])}}}
if(game.world===3){rect(4*T,3*T,5*T,4*T,'#43372b');rect(4*T,3*T,5*T,7,'#a8754a');for(let i=0;i<5;i++){rect((4+i)*T+5,4*T,3,3*T,'#bd8b52')}rect(21*T,3*T,5*T,4*T,'#43372b');rect(21*T,3*T,5*T,7,'#a8754a')}
if(game.world===4){for(const [x,y] of [[4,4],[22,4],[5,14],[22,14]]){circle(x*T+16,y*T+16,20,'#28382f');circle(x*T+15,y*T+14,13,'#506149');rect(x*T+13,y*T+20,5,14,'#74583c')}}
if(game.world===5){for(let i=0;i<9;i++){const x=3+(i*7)%23,y=3+(i*11)%12;circle(x*T+16,y*T+17,12,'#25485a');circle(x*T+16,y*T+15,7,'#47727c');rect(x*T+14,y*T+21,4,12,'#526b72')} }
if(game.world===0||game.world===6){for(const [x,y] of [[4,4],[23,4],[4,14],[23,14]]){rect(x*T,y*T,3*T,3*T,'#34393b');rect((x+1)*T,y*T,2*T,3*T,'#404a48');rect((x+1)*T+12,y*T+8,14,3,'#ceb57f')}}
}
function drawPortal(o){const pulse=Math.sin(game.tick*.07)*3+2,x=o.x*T,y=o.y*T;circle(x,y+6,22+pulse,'#8a6fd328');circle(x,y+6,15+pulse,'#b99c6045');rect(x-13,y-17,26,4,'#ccb47c');rect(x-16,y-14,4,35,'#9b8b68');rect(x+12,y-14,4,35,'#9b8b68');rect(x-11,y-11,22,25,'#635d7155');rect(x-2,y-14,4,27,'#f3d9a5')}
function drawActor(x,y,kind,dir='down',f=0){const px=x*T,py=y*T; // tiny pixel people with a grounded shadow
circle(px,py+8,11,'#06090c88');
if(kind==='player'){const blink=game.player.inv>0&&game.tick%8<4;if(blink)return;rect(px-8,py-18,16,22,'#171c27');rect(px-7,py-20,14,12,'#d3d5d0');rect(px-5,py-18,10,7,'#c6a9a0');rect(px-8,py-8,16,10,'#586b73');rect(px-7,py+1,5,8,'#202632');rect(px+2,py+1,5,8,'#202632');rect(px-7,py-21,5,3,'#a8d7ce');rect(px+4,py-16,3,2,'#dbd9a5');rect(px+8,py-6,4,8,'#8f9b9b');if(game.player.attack>0){const d=game.player.dir;const ax=px+(d==='left'?-19:d==='right'?19:0),ay=py+(d==='up'?-15:d==='down'?4:0);circle(ax,ay,10,'#d7f0dc88');circle(ax,ay,4,'#f5e8bc')}}
else if(kind==='guardian'||kind==='ally'||kind==='finalnpc'){rect(px-7,py-18,14,21,kind==='guardian'?'#d8c6a0':kind==='finalnpc'?'#c3d1cc':'#bb9c7d');rect(px-6,py-25,12,10,'#d6c6ab');rect(px-8,py-26,16,4,wColor());rect(px-3,py-13,3,3,'#e7d8ac');rect(px-6,py+2,4,7,'#242a2c');rect(px+2,py+2,4,7,'#242a2c');if(kind==='guardian')rect(px+8,py-8,2,18,'#dcc58a')}
else{const c=kind==='drone'?'#80dbe2':kind==='automaton'?'#c48f58':kind==='wraith'?'#b6dadd':'#b77c7c';circle(px,py-5,12,c);rect(px-8,py-7,16,10,'#20222b');rect(px-5,py-7,3,3,'#fa7770');rect(px+3,py-7,3,3,'#fa7770');rect(px-10,py+5,5,6,c);rect(px+5,py+5,5,6,c);rect(px-7,py+13,14,2,'#ffffff33');rect(px-7,py+13,14*(kind.hp??2)/2,2,'#d66b66')}}}
function wColor(){return worlds[game.world].accent}

