input.newString:
function wColor(){return worlds[game.world].accent}
function dialogue(speaker,lines,done){game.dialog={speaker,lines,index:0,done};el('speaker').textContent=speaker.toUpperCase();el('dialogText').textContent=lines[0];el('dialogOverlay').style.display='flex'}
function nextDialogue(){if(!game.dialog)return;const d=game.dialog;d.index++;if(d.index<d.lines.length){el('dialogText').textContent=d.lines[d.index];return}el('dialogOverlay').style.display='none';game.dialog=null;if(d.done)d.done()}
el('dialogNext').onclick=nextDialogue;
function closest(items){let best=null,dist=2.15;for(const it of items){const d=Math.hypot(game.player.x-it.x,game.player.y-it.y);if(d<dist){best=it;dist=d}}return best}
function interact(){if(game.dialog){nextDialogue();return}let n=closest(game.npcs);if(n){if(n.kind==='guardian'){dialogue(n.name,['Você acordou antes que o mundo terminasse de sonhar.','Meu nome não importa. O seu foi apagado de cinco realidades. Leve este pulso — não é uma arma. É uma pergunta que o universo ainda não respondeu.','Cada eco que encontrar lembrará aos mundos que eles existem. Mas também lembrará ao Singular que você existe.'],()=>{game.xp+=1;game.level=2;say('A Guardiã confiou a Xeon um pulso de ressonância.');updateUI()});return}
if(n.kind==='finalnpc'){dialogue(n.name,['Cinco ecos. Cinco mundos que voltaram a respirar. E você, Xeon — agora sabe de onde veio?','Você foi criada para ser a ponte. O Singular quer desfazer as fronteiras e devolver tudo a um silêncio perfeito.'],()=>showEndingChoice());return}
const lines=game.world===1?['As lanternas acendem quando alguém se lembra de casa. Hoje, lembraram de você.','O santuário está além da ponte. Não confie no sino: ele toca para o que ainda não chegou.']:game.world===2?['Sou Íris-7. Minha memória foi licenciada, depois revogada. Ainda assim, lembro de uma canção.','O núcleo está instável. Se puder, fale com os drones — talvez não precisem ser destruídos.']:game.world===3?['Esta caldeira moveu uma cidade inteira. Agora só move o medo de quem ficou.','A válvula lateral alimenta o santuário. Gire-a antes de seguir.']:game.world===4?['A floresta cresce sobre tudo que os reis chamaram de eterno.','O guardião não é seu inimigo. Mas não sabe mais a diferença.']:['Não há superfície neste mar. Só a lembrança de uma.','A anomalia imita o que perdemos. Não deixe que escolha por você.'];dialogue(n.name,lines);return}
const o=closest(game.objects);if(!o){return}
if(o.kind==='gate'){if(game.world===0){goWorld(1);return}if(game.world<6){if(game.echoes<game.world){dialogue('PORTAL', ['O limiar permanece fechado. Um eco deste mundo ainda está perdido.']);return}goWorld(game.world+1);return}}
if(o.kind==='shard'){if(game.world===3&&!game.objects.some(q=>q.kind==='valve'&&q.on)){dialogue('CALDEIRA',['A máquina está sem pressão. A válvula na ala oeste ainda pode ser aberta.']);return}if(game.enemies.length){dialogue('ECO INSTÁVEL',['O fragmento está cercado por uma ressonância hostil. Dissipe as ameaças primeiro.']);return}if(o.active){o.active=false;game.echoes=Math.min(5,game.echoes+1);game.xp+=2;if(game.xp>=game.level*3){game.xp=0;game.level++;game.player.max=Math.min(7,game.player.max+1);game.player.hp=game.player.max;say(`Xeon alcançou o nível ${game.level}. A ressonância fortaleceu seu corpo.`)}say(`Eco ${game.echoes}/5 recuperado. Uma lembrança atravessa Xeon.`);updateUI();save();}return}
if(o.kind==='valve'){if(!o.on){o.on=true;say('A válvula gira. A caldeira responde com um pulso profundo.');game.enemies.forEach(e=>e.hp=Math.max(1,e.hp));updateUI()}else say('A pressão está estável.');return}
if(o.kind==='heart'){dialogue('O CORAÇÃO DO SINGULAR',['Os cinco mundos respiram. O Singular oferece uma saída: fundir todas as realidades numa só — sem conflito, sem perda, sem diferença.','Xeon entende, enfim, o que foi criada para ser. Uma chave. Mas uma chave também pode escolher o que abre.'],()=>showEndingChoice())}}
function showEndingChoice(){const modal=document.querySelector('#dialogOverlay .modal');el('speaker').textContent='A ESCOLHA DE XEON';el('dialogText').textContent='O que Xeon faz com a ponte?';const actions=document.querySelector('.dialog-actions');actions.innerHTML='<button class="primary" id="choiceJoin">UNIR OS MUNDOS</button><button class="primary" id="choiceKeep">PRESERVAR AS FRONTEIRAS</button>';el('dialogOverlay').style.display='flex';document.getElementById('choiceJoin').onclick=()=>finish(true);document.getElementById('choiceKeep').onclick=()=>finish(false);function finish(join){actions.innerHTML='<button class="primary" id="dialogNext">CONTINUAR →</button>';document.getElementById('dialogNext').onclick=()=>{el('dialogOverlay').style.display='none';game.dialog=null};game.ended=true;save();dialogue('EPÍLOGO',join?['Xeon abre a ponte. Os mundos se tocam — não como um só, mas como vizinhos que finalmente se escutam. A diferença permanece. O medo também. Mas agora há escolha.','No santuário, uma nova lanterna se acende. Dentro dela, um nome: Xeon.']:['Xeon fecha a ponte, mas não apaga o caminho. Cada mundo permanece inteiro, livre para mudar sem pedir permissão ao outro.','A Guardiã sorri, como se enfim pudesse esquecer o próprio nome. Xeon parte sem saber quem a criou — e sabendo que isso já não decide quem ela é.'],()=>{say('Jornada concluída. Você pode continuar explorando ou iniciar outra história.');});}}
function goWorld(id){game.world=id;game.player.hp=game.player.max;makeMap();say(id===6?'O Singular chama por Xeon.':`Travessia: ${worlds[id].name}.`);save()}

