function goWorld(id){game.world=id;game.player.hp=game.player.max;makeMap();say(id===6?'O Singular chama por Xeon.':`Travessia: ${worlds[id].name}.`);save()}
function collides(x,y){const r=.27;return [[x-r,y-r],[x+r,y-r],[x-r,y+r],[x+r,y+r]].some(([a,b])=>game.walls.has(`${Math.floor(a)},${Math.floor(b)}`))}
function hurt(){const p=game.player;if(p.inv>0)return;p.hp--;p.inv=50;sfx(125,.09,'sawtooth');if(p.hp<=0){say('Xeon perdeu a forma, mas não a memória. O eco a recompõe.');p.hp=p.max;makeMap()}updateUI()}
function attack(){if(game.player.attack>0||game.player.dodge>0)return;game.player.attack=14;sfx(260,.07,'triangle');const p=game.player,d=game.player.dir;for(const e of game.enemies){const dx=e.x-p.x,dy=e.y-p.y,dist=Math.hypot(dx,dy);let forward=d==='up'?-dy:d==='down'?dy:d==='left'?-dx:dx,side=d==='up'||d==='down'?Math.abs(dx):Math.abs(dy);if(dist<1.6&&forward>-.1&&side<.9){e.hp--;e.hit=15;if(e.hp<=0){game.enemies=game.enemies.filter(q=>q!==e);game.xp++;say('Uma ameaça se desfaz em luz.');if(game.xp>=game.level*3){game.xp=0;game.level++;game.player.max=Math.min(7,game.player.max+1);game.player.hp=game.player.max;say(`Nível ${game.level}: vitalidade restaurada.`)}updateUI()}}}}
function dodge(){if(game.player.dodge>0)return;game.player.dodge=13;game.player.inv=20;sfx(380,.06,'sine')}
let audio=null;function sfx(freq,dur,type){if(!game.sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function update(){game.tick++;const p=game.player;if(p.inv>0)p.inv--;if(p.attack>0)p.attack--;if(p.dodge>0)p.dodge--;
let dx=0,dy=0;if(game.keys.ArrowLeft||game.keys.a)dx--;if(game.keys.ArrowRight||game.keys.d)dx++;if(game.keys.ArrowUp||game.keys.w)dy--;if(game.keys.ArrowDown||game.keys.s)dy++;if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l;p.dir=Math.abs(dx)>Math.abs(dy)?(dx<0?'left':'right'):(dy<0?'up':'down');const speed=p.dodge>0?.23:.105;let nx=p.x+dx*speed,ny=p.y+dy*speed;if(!collides(nx,p.y))p.x=nx;if(!collides(p.x,ny))p.y=ny}
for(const e of game.enemies){if(e.hit>0){e.hit--;continue}const vx=p.x-e.x,vy=p.y-e.y,d=Math.hypot(vx,vy);if(d<7&&d>.7){const s=e.speed*.025;const nx=e.x+vx/d*s,ny=e.y+vy/d*s;if(!collides(nx,e.y))e.x=nx;if(!collides(e.x,ny))e.y=ny}if(d<.67&&game.tick%36===0)hurt()}
let target=closest([...game.npcs,...game.objects]);const hint=el('hint');if(target){hint.textContent=target.name?`[E] FALAR COM ${target.name.toUpperCase()}`:target.kind==='gate'?'[E] ATRAVESSAR LIMIAR':target.kind==='shard'?'[E] TOCAR O ECO':target.kind==='valve'?'[E] GIRAR A VÁLVULA':target.kind==='heart'?'[E] TOCAR O CORAÇÃO':'[E] INTERAGIR';hint.classList.add('show')}else hint.classList.remove('show');}
function draw(){const w=worlds[game.world];rect(0,0,W,H,w.sky);drawDecoration();for(const o of game.objects){if(o.kind==='gate')drawPortal(o);if(o.kind==='shard'&&o.active){const y=o.y*T+Math.sin(game.tick*.08)*4;circle(o.x*T,y,20,'#f3d99425');ctx.save();ctx.translate(o.x*T,y);ctx.rotate(Math.PI/4);rect(-9,-9,18,18,'#e1c885');rect(-5,-5,10,10,'#fff0c2');ctx.restore()}if(o.kind==='valve'){circle(o.x*T,o.y*T,17,'#171c1e');circle(o.x*T,o.y*T,11,o.on?'#a6d09b':'#b98553');rect(o.x*T-2,o.y*T-16,4,32,'#d7c091');rect(o.x*T-15,o.y*T-2,30,4,'#d7c091')}if(o.kind==='heart'){circle(o.x*T,o.y*T,28,'#a97eac25');circle(o.x*T,o.y*T,14,'#dbc59b');circle(o.x*T,o.y*T,7,'#fff2ce')}}
for(const n of game.npcs)drawActor(n.x,n.y,n.kind);for(const e of game.enemies){const kind={hp:e.hp};drawActor(e.x,e.y,e.kind);if(game.world===5){} }
drawActor(game.player.x,game.player.y,'player',game.player.dir); // atmospheric motes
for(let i=0;i<22;i++){let x=(i*173+game.tick*(i%3+1)*.12)%W,y=(i*97+game.tick*(i%4+1)*.08)%H;rect(x,y,2,2,w.accent+'44')}
if(game.paused){rect(0,0,W,H,'#080b10b8');ctx.fillStyle='#efe5cf';ctx.textAlign='center';ctx.font='bold 30px Manrope';ctx.fillText('PAUSADO',W/2,H/2);ctx.font='14px Manrope';ctx.fillText('Pressione ESC para continuar',W/2,H/2+30)}}
function loop(){if(!game.started)return;if(!game.paused)update();draw();requestAnimationFrame(loop)}

