function loop(){if(!game.started)return;if(!game.paused)update();draw();requestAnimationFrame(loop)}
load();el('startBtn').onclick=start;el('saveBtn').onclick=save;el('resetBtn').onclick=()=>{if(confirm('Apagar a jornada salva e começar do início?'))reset()};el('soundBtn').onclick=()=>{game.sound=!game.sound;el('soundBtn').textContent='ÁUDIO: '+(game.sound?'ON':'OFF');if(game.sound)sfx(440,.1,'sine')};
window.addEventListener('keydown',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){if(game.dialog){nextDialogue()}else if(game.started){game.paused=!game.paused;say(game.paused?'Jornada pausada.':'A jornada continua.')}return}if(e.repeat)return;if(key==='e'||key==='Enter'){interact();return}if(e.key===' '){attack();return}if(key==='q'){dodge();return}game.keys[key]=true});window.addEventListener('keyup',e=>{let k=e.key.length===1?e.key.toLowerCase():e.key;game.keys[k]=false});
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();game.keys[k]=true;b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>game.keys[k]=false)});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();b.dataset.action==='attack'?attack():interact()}));
})();
